set -e
cd ~/kalunga-school/backend || { echo BACKEND_NOT_FOUND; exit 1; }
pwd
mkdir -p secrets apps/api apps/finance/services tmp
python3 - <<'PY'
import base64, pathlib
pathlib.Path('secrets/firebase-adminsdk.json').write_bytes(base64.b64decode(''''''))
pathlib.Path('apps/api/parents_push.py').write_bytes(base64.b64decode(''''''))
pathlib.Path('apps/finance/services/payment_service.py').write_bytes(base64.b64decode(''''''))
print('WROTE secrets + parents_push + payment_service')
PY
chmod 600 secrets/firebase-adminsdk.json
if [ -f ../.env ]; then ENV=../.env; elif [ -f .env ]; then ENV=.env; else ENV=../.env; touch "$ENV"; fi
grep -q '^FCM_PROJECT_ID=' "$ENV" 2>/dev/null && sed -i 's/^FCM_PROJECT_ID=.*/FCM_PROJECT_ID=institut-kalunga/' "$ENV" || echo 'FCM_PROJECT_ID=institut-kalunga' >> "$ENV"
grep -q '^FCM_SERVICE_ACCOUNT_FILE=' "$ENV" 2>/dev/null && sed -i 's|^FCM_SERVICE_ACCOUNT_FILE=.*|FCM_SERVICE_ACCOUNT_FILE=secrets/firebase-adminsdk.json|' "$ENV" || echo 'FCM_SERVICE_ACCOUNT_FILE=secrets/firebase-adminsdk.json' >> "$ENV"
echo "ENV=$ENV"
VENV=$(ls -d ~/virtualenv/kalunga-school/backend/*/bin/activate 2>/dev/null | head -n 1 || true)
if [ -n "$VENV" ]; then source "$VENV"; fi
pip install 'google-auth>=2.29' -q || python3 -m pip install 'google-auth>=2.29' -q || true
python3 - <<'PY'
from google.oauth2 import service_account
from google.auth.transport.requests import Request
creds = service_account.Credentials.from_service_account_file(
    'secrets/firebase-adminsdk.json',
    scopes=['https://www.googleapis.com/auth/firebase.messaging'],
)
creds.refresh(Request())
print('FCM_AUTH_OK', bool(creds.token))
PY
touch tmp/restart.txt
touch passenger_wsgi.py 2>/dev/null || true
echo DONE